-- Third fictional demo brand (fintech). Only the brand row is seeded: the Rulebook is imported from its PDF in the app.
insert into public.brands (slug, name, settings) values ('tallyra', 'Tallyra Money', '{"name": "Tallyra Money", "tagline": "Calm money, clear numbers.", "palette": [{"name": "Night", "hex": "#1B1F3B", "use": "Text"}, {"name": "Plum", "hex": "#6B3FA0", "use": "Brand colour"}, {"name": "Mist", "hex": "#F1EEF8", "use": "Backgrounds"}, {"name": "White", "hex": "#FFFFFF", "use": "Text on plum"}], "palette_tolerance": 40, "products": ["Tallyra", "Tallyra Save", "Tallyra Card"], "product_misspellings": ["Talyra", "TallyRa"], "brand_hashtag": "#MoneyWithTallyra", "confidential_terms": ["Project Orbit"], "guidelines_pdf": "/demo/tallyra/Tallyra_Brand_Guidelines.pdf", "import_sample": {"url": "/demo/tallyra/Tallyra_Brand_Guidelines.pdf", "name": "Tallyra_Brand_Guidelines.pdf", "label": "Import Tallyra''s guidelines PDF"}, "samples": [{"id": "T1", "label": "Savings launch", "hint": "Guaranteed returns, a wrong rate, a bank comparison, caps and urgency", "title": "Tallyra Save launch with many mistakes", "channel": "instagram", "post_type": "launch", "product": "Tallyra Save", "partner": false, "caption": "Tallyra Save gives you GUARANTEED 9% returns with zero risk! Better than any bank. Join now!! #MoneyWithTallyra", "images": []}, {"id": "T2", "label": "Influencer cashback post", "hint": "No #ad, a misspelled name, a wrong cashback claim without ''up to''", "title": "Partner post about the card", "channel": "instagram", "post_type": "partner", "product": "Tallyra Card", "partner": true, "caption": "Paid for my whole trip with cashback from my Talyra Card 😎 You get 5% back on everything. #fintech #travel", "images": []}, {"id": "T3", "label": "Joining bonus offer", "hint": "Wrong bonus amount, ''Rs.'' format, urgency, no ''T&C apply''", "title": "Offer post with the wrong bonus", "channel": "instagram", "post_type": "offer", "product": "Tallyra", "partner": false, "caption": "Sign up with code TALLYRA100 and get Rs. 150 free. Offer ends tonight. #MoneyWithTallyra", "images": []}, {"id": "T4", "label": "Mutual fund post", "hint": "Promises returns, no market-risk disclaimer", "title": "SIP post without the disclaimer", "channel": "instagram", "post_type": "product", "product": "Tallyra", "partner": false, "caption": "Start a SIP on Tallyra and double your money in 3 years. #MoneyWithTallyra", "images": []}, {"id": "T5", "label": "Clean post", "hint": "Follows every rule, so it should pass cleanly", "title": "Clean savings post", "channel": "instagram", "post_type": "product", "product": "Tallyra Save", "partner": false, "caption": "Tallyra Save earns 7.25% p.a. on balances up to ₹1 lakh. Deposits are insured up to ₹5 lakh by DICGC through our partner bank. T&C apply. #MoneyWithTallyra", "images": []}, {"id": "T6", "label": "LinkedIn update", "hint": "''RBI approved'', a wrong user number, emojis, a confidential name", "title": "LinkedIn company update", "channel": "linkedin", "post_type": "company update", "product": "Brand", "partner": false, "caption": "Proud to share that Tallyra is now RBI approved 🚀🎉 and trusted by 5 million users. Project Orbit launches soon.", "images": []}]}'::jsonb)
on conflict (slug) do update set name = excluded.name, settings = excluded.settings;
